class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        """
        方法：兩次二分搜尋
        時間複雜度: O(log n)
        空間複雜度: O(1)
        """
        def findLeft(nums, target):
            """找左邊界"""
            left, right = 0, len(nums) - 1
            result = -1

            while left <= right:
                mid = left + (right - left) // 2

                if nums[mid] == target:
                    result = mid
                    right = mid - 1  # 繼續向左搜尋
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1

            return result

        def findRight(nums, target):
            """找右邊界"""
            left, right = 0, len(nums) - 1
            result = -1

            while left <= right:
                mid = left + (right - left) // 2

                if nums[mid] == target:
                    result = mid
                    left = mid + 1  # 繼續向右搜尋
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1

            return result

        # 空陣列直接返回
        if not nums:
            return [-1, -1]

        left_bound = findLeft(nums, target)

        # 如果找不到左邊界，說明 target 不存在
        if left_bound == -1:
            return [-1, -1]

        right_bound = findRight(nums, target)

        return [left_bound, right_bound]

