#include <vector>

class Solution {
public:
    /**
     * 方法：兩次二分搜尋
     * 時間複雜度: O(log n)
     * 空間複雜度: O(1)
     */
    std::vector<int> searchRange(std::vector<int>& nums, int target) {
        if (nums.empty()) {
            return {-1, -1};
        }

        int leftBound = findLeft(nums, target);

        if (leftBound == -1) {
            return {-1, -1};
        }

        int rightBound = findRight(nums, target);

        return {leftBound, rightBound};
    }

private:
    int findLeft(const std::vector<int>& nums, int target) {
        int left = 0, right = nums.size() - 1;
        int result = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                result = mid;
                right = mid - 1;  // 繼續向左搜尋
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return result;
    }

    int findRight(const std::vector<int>& nums, int target) {
        int left = 0, right = nums.size() - 1;
        int result = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                result = mid;
                left = mid + 1;  // 繼續向右搜尋
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return result;
    }
};

