// 時間複雜度: O(log n)，空間複雜度: O(1)
function searchRange(nums: number[], target: number): number[] {
    // 回傳第一個「> x（strict）或 ≥ x」的索引
    const lowerBound = (x: number, strict: boolean): number => {
        let lo = 0, hi = nums.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (nums[mid] < x || (strict && nums[mid] === x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    const left = lowerBound(target, false);
    if (left === nums.length || nums[left] !== target) return [-1, -1];
    return [left, lowerBound(target, true) - 1];
}

