// 兩次二分：找第一個 ≥ target 與第一個 > target 的位置
// 時間複雜度: O(log n)，空間複雜度: O(1)
static int lowerBound(int* nums, int n, int x, bool strict) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < x || (strict && nums[mid] == x)) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int* searchRange(int* nums, int numsSize, int target, int* returnSize) {
    int* ans = malloc(sizeof(int) * 2);
    *returnSize = 2;
    int left = lowerBound(nums, numsSize, target, false);
    if (left == numsSize || nums[left] != target) {
        ans[0] = ans[1] = -1;
    } else {
        ans[0] = left;
        ans[1] = lowerBound(nums, numsSize, target, true) - 1;
    }
    return ans;
}

